package com.advocacia_microservice.caso.application;

import com.advocacia_microservice.cliente.domain.Contato;
import com.advocacia_microservice.cliente.infrastructure.persistence.ContatoRepository;
import com.advocacia_microservice.crm.infrastructure.CrmRepository;
import com.advocacia_microservice.equipe.application.EquipeService;
import com.advocacia_microservice.equipe.domain.PerfilEquipe;
import com.advocacia_microservice.empresa.domain.PapelEmpresa;
import com.advocacia_microservice.shared.exception.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @Transactional(readOnly=true)
public class CasosService {
    public record Opcao(UUID id,String nome) {}
    public record Opcoes(boolean podeEditar,boolean podeCriarCliente,boolean podeVerFinanceiro,List<Opcao> clientes,List<Opcao> grupos,List<Opcao> membros) {}
    public record NovoCliente(String nome,String documento,String telefone) {}
    public record Formulario(Integer versao,String titulo,UUID clienteId,UUID grupoId,UUID responsavelId,String partesAdversas,String observacoes,BigDecimal valorProposta,LocalDate propostaEm,NovoCliente novoCliente) {}
    public record Comercial(Integer versao,String desfecho,BigDecimal valorFechado,String motivoPerda) {}
    public record AnotacaoRequest(Integer versao,LocalDate data,String descricao) {}
    public record SituacaoRequest(Integer versao,String status) {}
    public record Anotacao(UUID id,LocalDate data,String descricao,String autor,OffsetDateTime criadoEm) {}
    public record Caso(UUID id,int versao,String titulo,String status,UUID clienteId,String cliente,UUID grupoId,String grupo,UUID responsavelId,String responsavel,String partesAdversas,String observacoes,BigDecimal valorProposta,LocalDate propostaEm,String desfecho,BigDecimal valorFechado,String motivoPerda,LocalDate fechadoEm,UUID leadId,OffsetDateTime criadoEm,OffsetDateTime atualizadoEm) {}
    public record Ficha(Caso caso,List<Anotacao> anotacoes,Map<String,Object> historicoLead) {}
    public record Pagina(List<Caso> itens,long total,int pagina,int tamanho) {}
    private final JdbcTemplate jdbc;private final EquipeService equipe;private final ContatoRepository contatos;private final CrmRepository json;
    private static final ZoneId ZONA=ZoneId.of("America/Sao_Paulo");
    public CasosService(JdbcTemplate jdbc,EquipeService equipe,ContatoRepository contatos,CrmRepository json){this.jdbc=jdbc;this.equipe=equipe;this.contatos=contatos;this.json=json;}
    private boolean edita(EquipeService.Acesso a){return a.papel()==PapelEmpresa.MASTER||Set.of(PerfilEquipe.ADMINISTRADOR,PerfilEquipe.ADVOGADO,PerfilEquipe.ASSISTENTE).contains(a.perfil());}
    EquipeService.Acesso acesso(UUID usuario,boolean escrita){var a=equipe.acesso(usuario);if(a.empresaId()==null||!a.modulos().contains("casos")||!equipe.ativo(usuario))throw new AccessDeniedException("Você não tem acesso a Casos desta empresa.");if(escrita&&!edita(a))throw new AccessDeniedException("Seu perfil permite apenas consultar os casos.");return a;}
    private String texto(String v,int limite,boolean requerido){v=Objects.requireNonNullElse(v,"").strip();if(v.length()>limite||(requerido&&v.isBlank()))throw new IllegalArgumentException("Confira os campos obrigatórios e seus limites.");return v;}
    private BigDecimal valor(BigDecimal v){if(v!=null&&(v.signum()<0||v.scale()>2||v.compareTo(new BigDecimal("99999999999999.99"))>0))throw new IllegalArgumentException("Informe valor positivo com até duas casas decimais.");return v;}
    private void data(LocalDate d){if(d!=null&&(d.getYear()<1900||d.getYear()>2200))throw new IllegalArgumentException("Data inválida.");}
    public Opcoes opcoes(UUID usuario){var a=acesso(usuario,false);var clientes=jdbc.query("SELECT id,nome FROM contato WHERE empresa_id=? ORDER BY LOWER(nome),id",(r,n)->new Opcao(r.getObject(1,UUID.class),r.getString(2)),a.empresaId());var grupos=jdbc.query("SELECT id,nome FROM cadastro_item WHERE empresa_id=? AND tipo='grupos' AND ativo=true ORDER BY nome",(r,n)->new Opcao(r.getObject(1,UUID.class),r.getString(2)),a.empresaId());var membros=jdbc.query("SELECT u.id,u.nome FROM empresa_usuario v JOIN usuario u ON u.id=v.usuario_id WHERE v.empresa_id=? AND u.status='ATIVO' ORDER BY u.nome",(r,n)->new Opcao(r.getObject(1,UUID.class),r.getString(2)),a.empresaId()).stream().filter(m->equipe.ativo(m.id())&&equipe.acesso(m.id()).modulos().contains("casos")).toList();return new Opcoes(edita(a),edita(a)&&a.modulos().contains("contatos"),a.modulos().contains("financeiro"),clientes,grupos,membros);}
    private static final String SELECT="SELECT c.*,ct.nome AS cliente,g.nome AS grupo,u.nome AS responsavel FROM caso c LEFT JOIN contato ct ON ct.id=c.cliente_id LEFT JOIN cadastro_item g ON g.id=c.grupo_id LEFT JOIN usuario u ON u.id=c.responsavel_id";
    private Caso mapear(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Caso(r.getObject("id",UUID.class),r.getInt("versao"),r.getString("titulo"),r.getString("status"),r.getObject("cliente_id",UUID.class),r.getString("cliente"),r.getObject("grupo_id",UUID.class),r.getString("grupo"),r.getObject("responsavel_id",UUID.class),r.getString("responsavel"),r.getString("partes_adversas"),r.getString("observacoes"),r.getBigDecimal("valor_proposta"),r.getObject("proposta_em",LocalDate.class),r.getString("desfecho"),r.getBigDecimal("valor_fechado"),r.getString("motivo_perda"),r.getObject("fechado_em",LocalDate.class),r.getObject("lead_id",UUID.class),r.getObject("criado_em",OffsetDateTime.class),r.getObject("atualizado_em",OffsetDateTime.class));}
    Caso exigir(UUID empresa,UUID id){return jdbc.query(SELECT+" WHERE c.empresa_id=? AND c.id=?",this::mapear,empresa,id).stream().findFirst().orElseThrow(()->new RecursoNaoEncontradoException("Caso não encontrado."));}
    private Caso versao(UUID empresa,UUID id,Integer v){var c=exigir(empresa,id);if(v==null||v!=c.versao())throw new ConflitoException("Este caso foi alterado em outra sessão. Recarregue a ficha.");return c;}
    public Pagina listar(UUID usuario,String busca,String status,int pagina,int tamanho){var empresa=acesso(usuario,false).empresaId();if(busca==null||busca.length()>150||!Set.of("ativo","encerrado","convertido","todos").contains(status)||pagina<0||pagina>1000000||tamanho<1||tamanho>100)throw new IllegalArgumentException("Filtros inválidos.");var filtro=" WHERE c.empresa_id=?";var args=new ArrayList<Object>();args.add(empresa);if(!status.equals("todos")){filtro+=" AND c.status=?";args.add(status);}if(!busca.isBlank()){filtro+=" AND (LOWER(c.titulo) LIKE ? ESCAPE '!' OR LOWER(ct.nome) LIKE ? ESCAPE '!')";var b="%"+busca.strip().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.add(b);args.add(b);}long total=jdbc.queryForObject("SELECT COUNT(*) FROM caso c LEFT JOIN contato ct ON ct.id=c.cliente_id"+filtro,Long.class,args.toArray());args.add(tamanho);args.add(pagina*tamanho);return new Pagina(jdbc.query(SELECT+filtro+" ORDER BY c.atualizado_em DESC,c.id LIMIT ? OFFSET ?",this::mapear,args.toArray()),total,pagina,tamanho);}
    @SuppressWarnings("unchecked") public Ficha buscar(UUID usuario,UUID id){var a=acesso(usuario,false);var c=exigir(a.empresaId(),id);var anotacoes=jdbc.query("SELECT n.*,u.nome FROM caso_anotacao n JOIN usuario u ON u.id=n.autor_id WHERE n.empresa_id=? AND n.caso_id=? ORDER BY n.data DESC,n.criado_em DESC,n.id",(r,n)->new Anotacao(r.getObject("id",UUID.class),r.getObject("data",LocalDate.class),r.getString("descricao"),r.getString("nome"),r.getObject("criado_em",OffsetDateTime.class)),a.empresaId(),id);var h=jdbc.queryForObject("SELECT historico FROM caso WHERE empresa_id=? AND id=?",String.class,a.empresaId(),id);return new Ficha(c,anotacoes,c.leadId()!=null&&a.modulos().contains("crm")?json.ler(h,Map.class):Map.of());}
    @Transactional public Ficha salvar(UUID usuario,UUID id,Formulario f){var a=acesso(usuario,true);var empresa=a.empresaId();contatos.bloquear(empresa);var anterior=id==null?null:versao(empresa,id,f.versao());if(anterior!=null&&!anterior.status().equals("ativo"))throw new ConflitoException("Somente casos ativos podem ser editados.");var titulo=texto(f.titulo(),300,true);var observacoes=texto(f.observacoes(),4000,false);var partes=texto(f.partesAdversas(),300,false);valor(f.valorProposta());data(f.propostaEm());var cliente=f.clienteId();var op=opcoes(usuario);
        if(f.novoCliente()!=null){if(cliente!=null||!op.podeCriarCliente())throw new AccessDeniedException("A criação de cliente exige acesso a Contatos.");var nc=f.novoCliente();cliente=UUID.randomUUID();var dados=new HashMap<String,String>();dados.put("nome",texto(nc.nome(),150,true));dados.put("documento",texto(nc.documento(),20,false));dados.put("telefone",texto(nc.telefone(),30,false));dados.put("tipo","Cliente");dados.put("tipo_pessoa","PF");dados.put("whatsapp","telefone");dados.put("carteira","casa");var novo=new Contato(cliente,empresa,0,dados,List.of(),List.of(),true);var documento=novo.dados().get("documento");if(!documento.isBlank()&&jdbc.queryForObject("SELECT COUNT(*) FROM contato_dado d JOIN contato c ON c.id=d.contato_id WHERE c.empresa_id=? AND d.campo='documento' AND REGEXP_REPLACE(d.valor,'[^0-9]','','g')=?",Long.class,empresa,documento)>0)throw new ConflitoException("Já existe um contato com este CPF. Selecione o cadastro existente.");contatos.salvar(novo,true);contatos.auditar(empresa,cliente,usuario,"CRIAR");}
        if(cliente!=null&&op.clientes().stream().noneMatch(c->c.id().equals(f.clienteId()))&&f.novoCliente()==null)throw new IllegalArgumentException("Selecione um contato da sua empresa.");
        if(f.grupoId()!=null&&op.grupos().stream().noneMatch(g->g.id().equals(f.grupoId()))&&(anterior==null||!f.grupoId().equals(anterior.grupoId())))throw new IllegalArgumentException("Selecione uma área ativa da empresa.");
        if(f.responsavelId()!=null&&op.membros().stream().noneMatch(m->m.id().equals(f.responsavelId())))throw new IllegalArgumentException("Selecione um responsável ativo com acesso a Casos.");
        if(id==null){id=UUID.randomUUID();jdbc.update("INSERT INTO caso(id,empresa_id,cliente_id,titulo,observacoes,historico,grupo_id,responsavel_id,partes_adversas,valor_proposta,proposta_em) VALUES (?,?,?,?,?,'{}',?,?,?,?,?)",id,empresa,cliente,titulo,observacoes,f.grupoId(),f.responsavelId(),partes,f.valorProposta(),f.propostaEm());}else jdbc.update("UPDATE caso SET cliente_id=?,titulo=?,observacoes=?,grupo_id=?,responsavel_id=?,partes_adversas=?,valor_proposta=?,proposta_em=?,versao=versao+1,atualizado_em=CURRENT_TIMESTAMP WHERE empresa_id=? AND id=?",cliente,titulo,observacoes,f.grupoId(),f.responsavelId(),partes,f.valorProposta(),f.propostaEm(),empresa,id);return buscar(usuario,id);}
    @Transactional public Ficha comercial(UUID usuario,UUID id,Comercial f){var empresa=acesso(usuario,true).empresaId();contatos.bloquear(empresa);var c=versao(empresa,id,f.versao());if(!c.status().equals("ativo"))throw new ConflitoException("Este caso não está ativo.");if(f.desfecho()==null||!Set.of("","fechado","perdido","desistiu","sem_resposta").contains(f.desfecho()))throw new IllegalArgumentException("Desfecho inválido.");boolean fechado=f.desfecho().equals("fechado");var v=fechado?valor(f.valorFechado()):null;var motivo=fechado||f.desfecho().isBlank()?"":texto(f.motivoPerda(),2000,false);jdbc.update("UPDATE caso SET desfecho=?,valor_fechado=?,motivo_perda=?,fechado_em=?,versao=versao+1,atualizado_em=CURRENT_TIMESTAMP WHERE empresa_id=? AND id=?",f.desfecho(),v,motivo,fechado?(c.fechadoEm()==null?LocalDate.now(ZONA):c.fechadoEm()):null,empresa,id);return buscar(usuario,id);}
    @Transactional public Ficha anotar(UUID usuario,UUID id,AnotacaoRequest f){var empresa=acesso(usuario,true).empresaId();contatos.bloquear(empresa);var c=versao(empresa,id,f.versao());if(!c.status().equals("ativo"))throw new ConflitoException("Este caso não está ativo.");if(f.data()==null)throw new IllegalArgumentException("Informe a data da anotação.");data(f.data());var descricao=texto(f.descricao(),4000,true);jdbc.update("INSERT INTO caso_anotacao(id,empresa_id,caso_id,data,descricao,autor_id) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),empresa,id,f.data(),descricao,usuario);jdbc.update("UPDATE caso SET versao=versao+1,atualizado_em=CURRENT_TIMESTAMP WHERE empresa_id=? AND id=?",empresa,id);return buscar(usuario,id);}
    @Transactional public Ficha situacao(UUID usuario,UUID id,SituacaoRequest f){var empresa=acesso(usuario,true).empresaId();contatos.bloquear(empresa);var c=versao(empresa,id,f.versao());if(c.status().equals("convertido")||f.status()==null||!Set.of("ativo","encerrado").contains(f.status()))throw new IllegalArgumentException("Situação inválida.");jdbc.update("UPDATE caso SET status=?,versao=versao+1,atualizado_em=CURRENT_TIMESTAMP WHERE empresa_id=? AND id=?",f.status(),empresa,id);return buscar(usuario,id);}
    @Transactional public void excluir(UUID usuario,UUID id,int v){var empresa=acesso(usuario,true).empresaId();contatos.bloquear(empresa);var c=versao(empresa,id,v);if(c.leadId()!=null||c.status().equals("convertido"))throw new ConflitoException("Este caso possui histórico vinculado. Encerre para preservá-lo.");if(jdbc.queryForObject("SELECT COUNT(*) FROM caso_financeiro WHERE empresa_id=? AND caso_id=? AND versao>0",Integer.class,empresa,id)>0)throw new ConflitoException("Este caso possui histórico financeiro. Encerre para preservá-lo.");jdbc.update("DELETE FROM caso WHERE empresa_id=? AND id=?",empresa,id);}
}
